//! libp2p transport substrate for Pillar.
//!
//! This crate wires together the pieces of the P2 "libp2p substrate" milestone:
//!
//! - [`gossipsub`] for the append-only event log (pub/sub broadcast).
//! - Kademlia (`kad`) for peer discovery / bootstrap.
//! - `relay` + `dcutr` for NAT traversal: a relayed connection first, then an
//!   attempted direct connection upgrade through hole punching.
//!
//! Tor/onion routing is deliberately out of scope here: it is an optional
//! overlay transport, not part of the core substrate.
//!
//! The `*Event` enums below are generated by `#[derive(NetworkBehaviour)]`
//! and cannot themselves carry doc comments on their variants.
#![allow(missing_docs)]
//!
//! The crate exposes two swarm flavours:
//!
//! - [`build_event_swarm`] — a "normal" node behaviour (gossipsub + kademlia +
//!   identify) over TCP and QUIC. Used by nodes that are directly reachable.
//! - [`build_relay_server_swarm`] / [`build_relay_client_swarm`] — a relay
//!   server and the relay-aware client behaviour (gossipsub + kademlia +
//!   identify + relay client + dcutr) used by nodes that need a relay to be
//!   reached (e.g. because they are behind a NAT).

use libp2p::{
    core::{muxing::StreamMuxerBox, upgrade::Version},
    dcutr, gossipsub, identify,
    identity::Keypair,
    kad, noise,
    pnet::{PnetConfig, PreSharedKey},
    relay,
    swarm::behaviour::toggle::Toggle,
    tcp, upnp, yamux, PeerId, Swarm, Transport,
};

